    /// <summary>长父键截断后仍是另一条真实路径，必须以实际存储与输入比较拒绝。</summary>
    private static long LongParent(int role)=>long.Parse(Id(First+role-1)+"1",CultureInfo.InvariantCulture);
    /// <summary>只在本事务暂停，独立连接确认目标路径锁确实已取得。</summary>
    private sealed class Observer:IRecordMutationObserver
    {
        internal int Count;private bool armed;internal TaskCompletionSource Entered=new(TaskCreationOptions.RunContinuationsAsynchronously),Release=new(TaskCreationOptions.RunContinuationsAsynchronously);
        /// <summary>每次等待使用新信号，不复用上一轮完成状态。</summary>
        internal void Arm(){armed=true;Entered=new(TaskCreationOptions.RunContinuationsAsynchronously);Release=new(TaskCreationOptions.RunContinuationsAsynchronously);}
        /// <summary>恢复普通通知行为。</summary>
        internal void Disarm()=>armed=false;
        /// <summary>失败和持锁标记只来自固定样本值。</summary>
        public async Task BeforeCommitAsync(RecordMutationContext context,CancellationToken token=default){Count++;if(context.SubmittedFields.Values.Any(value=>Equals(value,"尾部失败")))throw new InvalidOperationException("固定尾部失败");if(armed&&context.SubmittedFields.Values.Any(value=>Equals(value,"锁持有"))){Entered.TrySetResult();await Release.Task.WaitAsync(TimeSpan.FromSeconds(25),token);}}
    }
    /// <summary>非严格模式仅在当前测试连接生效，不修改服务器全局设置。</summary>
    private sealed class NonStrict:IRecordMutationGuard
    {
        internal bool Enabled;
        /// <summary>准备阶段不修改身份或项目配置。</summary>
        public Task BeforeMutationAsync(RecordMutationPreparation preparation,CancellationToken token=default)=>Task.CompletedTask;
        /// <summary>只调整当前事务连接的测试模式。</summary>
        public async Task BeforeWriteAsync(RecordMutationValidation validation,CancellationToken token=default){if(!Enabled)return;await using var command=validation.Transaction.Connection!.CreateCommand();command.Transaction=validation.Transaction;command.CommandText="SET SESSION sql_mode=''";await command.ExecuteNonQueryAsync(token);}
    }
    /// <summary>固定普通身份只用于HTTP夹具，目标撤权与客户端私有字段仍按原合同拒绝。</summary>
    private sealed class Auth(IHttpContextAccessor accessor):IRuntimeAuthorization
    {
        /// <summary>身份由测试宿主固定，不读取客户端项目选择。</summary>
        public RuntimeActor RequireActor()=>new(998,"R1重复来源验收",false,Id(Project),"5");
        /// <summary>撤目标读取权限时仍允许原来源清空及内部缓存刷新。</summary>
        public void RequirePagePermission(string page,string operation){if(operation=="list"&&accessor.HttpContext!.Request.Headers.ContainsKey("denyTargets"))throw new UnauthorizedAccessException("没有目标读取权限。");}
    }
    /// <summary>原R成功码是读取data的前提。</summary>
    private static JsonElement Data(JsonElement value){Assert.Equal(200,value.GetProperty("code").GetInt32());return value.GetProperty("data");}
    /// <summary>ID全程保持精确整数文本。</summary>
    private static string Id(long id)=>id.ToString(CultureInfo.InvariantCulture);
    /// <summary>只接受固定测试字段，不拼接业务SQL值。</summary>
    private static Dictionary<string,object?> D(params object?[] values){var result=new Dictionary<string,object?>();for(var i=0;i<values.Length;i+=2)result.Add((string)values[i]!,values[i+1]);return result;}
    /// <summary>只对清理前结构和行摘要双核对的本nonce自有表执行DDL。</summary>
    private static async Task Sql(DatabaseSession session,string sql){await using var connection=session.Provider.CreateConnection(session.Options);await connection.OpenAsync();await using var command=connection.CreateCommand();command.CommandText=sql;await command.ExecuteNonQueryAsync();}
